// Sonic Generations - Precompiled Shader Cache
// Uses XenosRecomp generated cache for fast startup, no runtime stutter
// Based on Unleashed Recompiled shader cache system
// Real cache: 6404 shaders, Vulkan SPIR-V, ZSTD+smol-v compressed

#pragma once

#include <cstdint>
#include <cstddef>
#include <vector>
#include <unordered_map>
#include <memory>
#include <string>
#include <mutex>

// ============================================================================
// Low-level format - MUST match XenosRecomp generated shader_cache_data.cpp
// This is the format generated by XenosRecomp main.cpp:
//   { hash, dxilOffset, dxilSize, spirvOffset, spirvSize, airOffset, airSize, specMask, name }
// ============================================================================

struct ShaderCacheEntry {
    uint64_t hash;
    size_t dxilOffset;
    size_t dxilSize;
    size_t spirvOffset;
    size_t spirvSize;
    size_t airOffset;
    size_t airSize;
    uint64_t specConstantsMask;
    const char* name;
};

// Generated data from XenosRecomp (in shader_cache_data.cpp)
extern ShaderCacheEntry g_shaderCacheEntries[];
extern const uint8_t g_compressedSpirvCache[];
extern const size_t g_spirvCacheCompressedSize;
extern const size_t g_spirvCacheDecompressedSize;
extern const size_t g_shaderCacheEntryCount;

// Optional DXIL/AIR if present (vulkan cache only has SPIR-V)
extern const uint8_t g_compressedDxilCache[];
extern const size_t g_dxilCacheCompressedSize;
extern const size_t g_dxilCacheDecompressedSize;

// ============================================================================
// High-level cache wrapper - provides decompressed SPIR-V on demand
// ============================================================================

namespace sonic_native {
namespace hedgehog {

// Decoded shader ready for Vulkan
struct DecodedShader {
    uint64_t hash;
    std::vector<uint32_t> spirv; // Decoded SPIR-V (not smol-v, not zstd)
    uint64_t specConstantsMask;
    std::string name;
    uint32_t stage; // 0=VS, 2=PS (from XenosRecomp: 0=VS, 2=PS in last field? Actually spec mask is 2nd last, stage not stored - we infer from name or keep as PS/VS)
    bool isValid = false;
};

// High-performance shader cache with ZSTD+smol-v decompression
// Based on UnleashedRecomp's video.cpp LoadEmbeddedResources + CreateShader
class ShaderCache {
public:
    static ShaderCache& Get();
    
    bool Initialize();
    void Shutdown();
    
    // Find shader by hash - returns decoded SPIR-V if found
    // This decompresses on demand: ZSTD (once) + smol-v per shader
    const DecodedShader* Find(uint64_t hash) const;
    
    // For compatibility with old API
    struct LegacyEntry {
        uint64_t hash;
        const uint32_t* spirv;
        size_t spirvSize;
        const uint8_t* dxil;
        size_t dxilSize;
        uint32_t stage;
        std::string name;
    };
    
    // Get raw entry without decoding (for stats)
    const ShaderCacheEntry* FindRaw(uint64_t hash) const;
    
    // Stats
    struct Stats {
        uint64_t totalShaders = 0;
        uint64_t cacheHits = 0;
        uint64_t cacheMisses = 0;
        size_t memoryUsage = 0;
        size_t decompressedCacheSize = 0;
    };
    const Stats& GetStats() const { return stats_; }
    
    void DumpInfo() const;
    bool IsComplete() const { return rawEntries_.size() >= 6404; }
    bool IsInitialized() const { return initialized_; }
    
    // For shader_translator compatibility
    struct SimpleEntry {
        uint64_t hash;
        const uint32_t* spirv;
        size_t spirvSize;
        const uint8_t* dxil;
        size_t dxilSize;
        uint32_t stage;
        std::string name;
    };
    
private:
    ShaderCache() = default;
    
    bool DecompressGlobalCache();
    bool DecodeShader(const ShaderCacheEntry& raw, DecodedShader& out) const;
    
    mutable std::unordered_map<uint64_t, DecodedShader> decodedCache_;
    std::unordered_map<uint64_t, const ShaderCacheEntry*> rawEntries_;
    mutable std::mutex cacheMutex_;
    
    // Global decompressed buffer (ZSTD decompressed, still smol-v encoded)
    std::unique_ptr<uint8_t[]> decompressedCache_;
    size_t decompressedCacheSize_ = 0;
    
    Stats stats_;
    bool initialized_ = false;
};

} // namespace hedgehog
} // namespace sonic_native
